using System;using System.Reflection;using System.Linq;using NAudio.CoreAudioApi;using NAudio.Wave;
// Management-only probe: initializes streams but never calls Play or changes any endpoint setting.
class OutputFormatsLive {
 sealed class Empty:IWaveProvider {public int Reads;public WaveFormat WaveFormat{get{return new WaveFormat(44100,16,2);}}public int Read(byte[] b,int o,int n){Reads++;Array.Clear(b,o,n);return n;}}
 static string Default(MMDeviceEnumerator e,Role role){using(var d=e.GetDefaultAudioEndpoint(DataFlow.Render,role))return d.ID;}
 static int Main(){try{int failures=0;using(var e=new MMDeviceEnumerator()){var roles=new[]{Role.Console,Role.Multimedia,Role.Communications};var before=roles.Select(r=>Default(e,r)).ToArray();foreach(var d in e.EnumerateAudioEndPoints(DataFlow.Render,DeviceState.Active))using(d){Console.WriteLine("DEVICE "+d.FriendlyName);try{using(var oldDevice=e.GetDevice(d.ID))using(var old=new WasapiOut(oldDevice,AudioClientShareMode.Shared,true,100)){old.Init(new Empty());Console.WriteLine("OLD initialize OK");}}catch(Exception ex){Console.WriteLine("OLD initialize failed 0x"+ex.HResult.ToString("X8"));}
  var type=typeof(AirBridge.Routing.GraphRuntime).Assembly.GetType("AirBridge.Routing.PlaybackOutput");var source=new Empty();try{using(var output=(IDisposable)Activator.CreateInstance(type,new object[]{d.ID,source,100,new Action<string>(s=>Console.WriteLine("NEW "+s))})){if(source.Reads!=0)throw new Exception("Initialization consumed source audio");Console.WriteLine("NEW initialize OK; no playback or source reads");}}catch(Exception ex){failures++;Console.WriteLine("NEW FAILED "+ex.GetBaseException().Message);}
 }if(!roles.Select(r=>Default(e,r)).SequenceEqual(before))throw new Exception("Default outputs changed outside this probe");Console.WriteLine("PASS no Play called; all three default output roles unchanged");}Console.WriteLine("New initialization failures="+failures);return failures==0?0:1;}catch(Exception ex){Console.WriteLine("FAIL "+ex.GetBaseException().Message);return 1;}}
}
